    "build": "HTML5, JavaScript",
    "dev": "Doppler Creative",
    "about": "Boxel Rebound has a dedicated place in the Fireboy-Watergirl Unblocked catalog for players looking for platformer games. The page keeps the playable build and useful catalog details together instead of sending you through multiple menus. Developer information in the catalog lists Doppler Creative. The recorded release date is April 20, 2017. The listed technology is HTML5, JavaScript. Boxel Rebound is a poopular Chrome extension platformer game, brought to the web by MacVG. In this fast-paced reaction game, you need to control a block to jump over obstacles, spikes, and cliffs. Try to reach the end as fast as possible! As you advance, levels will be getting harder and there will also be other techniques like trampolines, speed up blocks, and resizers. Jump at the right time to avoid dying and get as many points as possible! Other than the preloaded 50 levels, you can also create your own unique fun levels and enjoy it yourself or with friends! Have fun! This build has documented input notes: Space Bar / Up Arrow / Click: Jump. Because embedded versions can differ, the prompts shown inside {name} should take priority if they conflict with a static note. The page also keeps Popular Games close by, making it easy to switch from Boxel Rebound to another browser title without losing your place in the library.",
    "controls": [
      "Space Bar / Up Arrow / Click: Jump"
    ],
    "originalAbout": "Boxel Rebound is a poopular Chrome extension platformer game, brought to the web by MacVG. In this fast-paced reaction game, you need to control a block to jump over obstacles, spikes, and cliffs. Try to reach the end as fast as possible! As you advance, levels will be getting harder and there will also be other techniques like trampolines, speed up blocks, and resizers. Jump at the right time to avoid dying and get as many points as possible! Other than the preloaded 50 levels, you can also create your own unique fun levels and enjoy it yourself or with friends! Have fun!"
