    "dev": "RobKaySF",
    "about": "Slope has a dedicated place in the Fireboy-Watergirl Unblocked catalog for players looking for reaction games. The page keeps the playable build and useful catalog details together instead of sending you through multiple menus. Developer information in the catalog lists RobKaySF. The recorded release date is September 30, 2014. The listed technology is Unity WebGL. In Slope, this exciting fast-paced action game, you need to navigate a ball down an endless slope with breakneck speeds! There are cliffs, curves, blocks, and all sorts of obstacles that you need to dodge and jump! Don't hit any red blocks, and don't go off the slope! There are speed up ramps that speeds up the ball even more, making the game even more intense! Try to avoid falling off the slope for as long as possible and get the most points! React fast, navigate accurately, and stay on track! This build has documented input notes: Left Arrow: Go Left; Right Arrow: Go right; Note: WASD keys also work. Because embedded versions can differ, the prompts shown inside {name} should take priority if they conflict with a static note. After playing Slope, the related-games area is the quickest way to stay in the same part of the catalog without returning to the homepage.",
