    "about": "Endless Truck joins the Fireboy-Watergirl Unblocked library as a physics-based strategy games entry. Fireboy-Watergirl Unblocked puts the player first and keeps the supporting information below it so the page stays useful without getting in the way. Developer information in the catalog lists Famobi. The recorded release date is September 2016. The listed technology is HTML5, JavaScript. In this fun truck driving game, you need to control your car to complete the missions of the level, while driving through obstacles and keeping fuel in check. Each level has three missions, and to beat the level, you need to complete all of them in one run. Tilt left or tilt right to perform flips in midair, and adjust the truck's balance to land perfectly and receive a boost! There are fuel boxes that recharge your fuel. Don't miss them or you'll run out of gas! Jump to get over obstacles. Every time you do a stunt or collect them during the drive, you earn cash which you can use to upgrade your truck and drive even longer and beat your personal record! This build has documented input notes: Left Arrow: Tilt Left; Right Arrow: Tilt Right; Space: Jump. Because embedded versions can differ, the prompts shown inside {name} should take priority if they conflict with a static note. If you are browsing rather than searching for one specific title, Endless Truck can also be reached again through search, favorites and the matching catalog category.",
