    "dev": "Candywriter",
    "about": "If BitLife is the game you came for, this page keeps the route simple: launch the browser version, review the available game information, then move to related titles when you are ready for something different. Developer information in the catalog lists Candywriter. The recorded release date is September 29, 2018. The listed technology is Unity WebGL. In BitLife, this exciting life simulation game, you can literally be anyone. Write your own life story from birth to death however you like by choosing different options, do different things, and make different decisions. Click on the green button to age, and as you age, there will be situations where you'll need to make the best decisions that will make your character successful. You can get a dream job, get married, have children... you can do anything. Experience countless lives all in your control in BitLife! This build has documented input notes: Click: Action. Because embedded versions can differ, the prompts shown inside {name} should take priority if they conflict with a static note. The page also keeps Popular Games close by, making it easy to switch from BitLife to another browser title without losing your place in the library.",
